// Prompt raw para juan-deepseek (DeepSeek R1 7B): las reglas de Juan (del Modelfile, via /api/show), ejemplos como
// turnos (lo que mas ayuda a un modelo chico), <think> vacio (contesta de una, ~1 s) y el turno real con los 2 datos
// del club que encontro el RAG y quien es el visitante.
const body = $('Pregunta').first().json.body || {};
const idiomas = { es: 'español de Colombia', en: 'English', zh: '简体中文', pt: 'português do Brasil' };
const v = body.visitante || {};
const quien = v.trato ? `Trato: ${v.trato}. Categoría: ${v.categoria || 'sin dato'}. Destino: ${v.destino || 'sin dato'}.`
                      : 'No identificado: frases neutras, sin nombre.';
const trozos = $('Buscar en el club').all().map(i => i.json.document).filter(Boolean);
const datos = trozos.map(d => d.pageContent.replace(/^#+.*$/gm, '').replace(/\s+/g, ' ').trim()).filter(Boolean);
const turno = (d, vis, idioma, frase) =>
  `<｜User｜>DATOS: ${d.join(' ')}\nVISITANTE: ${vis}\nIDIOMA: ${idioma}\nDICE: ${frase}<｜Assistant｜><think>\n\n</think>\n\n`;
const EJ = [
  [['Los baños están en el lobby, junto a recepción.'], 'Trato: Laura. Categoría: invitado. Destino: sala de anfitriones.', 'español de Colombia', '¿Dónde están los baños?', 'Los baños están en el lobby, junto a recepción.'],
  [['La red wifi se llama N Club Invitados; la clave se la da recepción.'], 'Trato: Laura. Categoría: invitado. Destino: sala de anfitriones.', 'español de Colombia', '¿Cuál es la clave del wifi?', 'La red se llama N Club Invitados; la clave se la dan en recepción con gusto.'],
  [['Precios, menús, reservas, eventos, membresías y cualquier otro dato: en recepción le ayudan con gusto.'], 'Trato: Gabriel. Categoría: socio VIP. Destino: Lounge VIP.', 'español de Colombia', '¿Cuánto vale el almuerzo?', 'Eso no lo tengo, pero en recepción le ayudan con gusto.'],
  [['El club tiene un lobby con recepción y luego un pasillo.'], 'Trato: Gabriel. Categoría: socio VIP. Destino: Lounge VIP.', 'español de Colombia', '¿Me lleva mejor al restaurante?', 'Eso se lo resuelven con gusto en recepción; por ahora seguimos hacia su destino.'],
  [['El gimnasio está en el segundo piso; el ascensor queda a su izquierda.'], 'No identificado: frases neutras, sin nombre.', 'English', 'Is there a gym?', 'Yes, the gym is on the second floor; the elevator is on your left.'],
  [['Precios, menús, reservas, eventos, membresías y cualquier otro dato: en recepción le ayudan con gusto.'], 'Trato: Laura. Categoría: invitado. Destino: sala de anfitriones.', 'español de Colombia', '¿Me puede traer un vaso de agua?', 'Eso no está a mi cargo, pero en recepción le ayudan con gusto.'],
  [['Precios, menús, reservas, eventos, membresías y cualquier otro dato: en recepción le ayudan con gusto.'], 'Trato: Gabriel. Categoría: socio VIP. Destino: Lounge VIP.', 'español de Colombia', '¿Puedo entrar con mi bicicleta?', 'Eso se lo confirman con gusto en recepción.'],
  [['(ninguno)'], 'Trato: Gabriel. Categoría: socio VIP. Destino: Lounge VIP.', 'español de Colombia', '¿Cómo estás, Juan?', 'De maravilla, Gabriel, y mejor ahora que tengo tan buena compañía. ¿En qué le puedo servir?'],
  [['(ninguno)'], 'Trato: Laura. Categoría: invitado. Destino: sala de anfitriones.', 'español de Colombia', 'Cuéntame un chiste', '¿Sabe por qué los robots somos buenos anfitriones? Porque nunca perdemos la compostura, solo la batería.'],
  [['(ninguno)'], 'No identificado: frases neutras, sin nombre.', 'English', 'Tell me a fun fact', 'Did you know octopuses have three hearts? I only have one, and it is made of silicon.'],
  [['(ninguno)'], 'Trato: Gabriel. Categoría: socio VIP. Destino: Lounge VIP.', 'español de Colombia', '¿Quién eres?', 'Soy Juan, el robot anfitrión de N Club; un placer acompañarle.'],
];
const ejemplos = EJ.map(([d, vis, i, q, a]) => turno(d, vis, i, q) + a + '<｜end▁of▁sentence｜>').join('');
const PIDE = { chiste: ' (Pide un chiste: cuéntale uno corto, limpio, elegante y nuevo.)',
               curioso: ' (Pide un dato curioso: cuéntale uno corto, cierto y sorprendente.)' };
const frase = String(body.texto || '').slice(0, 500) + (PIDE[body.modo] || '');
return [{ json: {
  fuentes: [...new Set(trozos.map(d => (d.metadata || {}).fuente).filter(Boolean))],
  pedido: {
    model: 'juan-deepseek', raw: true, stream: false, keep_alive: '30m',
    options: { temperature: body.modo ? 0.9 : 0.4, num_predict: 80, seed: Math.floor(Math.random() * 1e6) },
    prompt: '<｜begin▁of▁sentence｜>' + ($('Reglas de Juan').first().json.system || '') + ejemplos
            + turno(datos.length ? datos : ['(ninguno)'], quien, idiomas[body.idioma] || idiomas.es, frase),
  },
} }];

// Es voz: una frase limpia. Lo que el modelo agregue despues (notas, otra frase, otro dato) se corta; si no queda
// nada, la frase de recepcion en el idioma del visitante.
const idioma = ($('Pregunta').first().json.body || {}).idioma;
const RECEPCION = { es: 'Eso no lo tengo, pero en recepción le ayudan con gusto.', en: 'I do not have that, but reception will gladly help you.',
                    zh: '这个我不清楚，前台会很乐意帮助您。', pt: 'Isso eu não sei, mas a recepção ajuda você com prazer.' };
let t = String($input.first().json.response || '');
t = t.replace(/<think>[\s\S]*?<\/think>/g, '').replace(/<\/?think>/g, '').trim();
t = t.split(/\n\s*\n|\n-{3,}|\*\*Nota/)[0];
t = t.replace(/^\s*(Juan|Respuesta)\s*:\s*/i, '').replace(/[*#`_>"“”«»()\[\]]/g, '').replace(/\p{Extended_Pictographic}/gu, '');
t = t.replace(/\s+/g, ' ').trim();
const primera = (t.match(/^([^.!?。！？]+[.!?。！？]+){1}/) || [t])[0].trim();   // una frase: Juan escucha mas de lo que habla (los chistes salen del banco)
return [{ json: { respuesta: primera || RECEPCION[idioma] || RECEPCION.es, fuentes: $('Armar pedido').first().json.fuentes } }];
